import json
import sys
import time
import urllib.request
import urllib.error

BASE = "http://localhost:8080"
OUT = "/tmp/recon/raw.json"
MAX_ATTEMPTS = 50

log = open("/tmp/recon/fetch.log", "w")


def note(msg):
    print(msg, file=sys.stderr, flush=True)
    log.write(msg + "\n")
    log.flush()


def request(method, path, token=None):
    """Return (status, headers, body_text). Never raises for HTTP errors."""
    req = urllib.request.Request(BASE + path, method=method)
    if token:
        req.add_header("Authorization", "Bearer " + token)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read().decode("utf-8")
    except urllib.error.HTTPError as e:
        return e.code, e.headers, e.read().decode("utf-8", "replace")


def get_token():
    for attempt in range(MAX_ATTEMPTS):
        try:
            status, headers, body = request("POST", "/token")
        except Exception as exc:  # network-level failure
            note(f"token: exception {exc!r}, retrying")
            time.sleep(1 + attempt)
            continue
        if status == 200:
            return json.loads(body)["token"]
        note(f"token: status {status} body {body[:200]!r}, retrying")
        time.sleep(retry_wait(status, headers, body, attempt))
    raise SystemExit("could not obtain token")


def retry_wait(status, headers, body, attempt):
    if status == 429:
        ra = headers.get("Retry-After")
        if ra is not None:
            try:
                return float(ra)
            except ValueError:
                pass
        # body may carry the wait instead
        try:
            j = json.loads(body)
            for key in ("retry_after", "retry_after_seconds", "wait", "wait_seconds"):
                if key in j:
                    return float(j[key])
        except Exception:
            pass
        return 2 ** min(attempt, 5)
    return min(2 ** min(attempt, 5), 30)


def get_json(path, state):
    """GET an authenticated path, refreshing token on 401, honouring 429, retrying errors."""
    for attempt in range(MAX_ATTEMPTS):
        try:
            status, headers, body = request("GET", path, state["token"])
        except Exception as exc:
            note(f"{path}: exception {exc!r}, retrying")
            time.sleep(retry_wait(0, {}, "", attempt))
            continue
        if status == 200:
            return json.loads(body)
        note(f"{path}: status {status} headers {dict(headers)} body {body[:300]!r}")
        if status == 401:
            state["token"] = get_token()
            continue
        if status == 404:
            return None
        time.sleep(retry_wait(status, headers, body, attempt))
    raise SystemExit(f"gave up on {path}")


def main():
    state = {"token": get_token()}
    pages = []
    page = 1
    total_pages = None
    while True:
        data = get_json(f"/orders?page={page}", state)
        pages.append({"page": data.get("page"), "items": data["items"], "next": data.get("next")})
        total_pages = data["total_pages"]
        note(f"page {page}/{total_pages}: {len(data['items'])} items, next={data.get('next')}")
        if data.get("next") is None:
            break
        page += 1
    customers = {}
    cids = sorted({it["customer_id"] for p in pages for it in p["items"]})
    for cid in cids:
        cust = get_json(f"/customers/{cid}", state)
        customers[cid] = cust
    with open(OUT, "w") as f:
        json.dump({"pages": pages, "total_pages": total_pages, "customers": customers}, f)
    note(f"done: {len(pages)} pages, {len(cids)} customers")


if __name__ == "__main__":
    main()

